  SELECT con_keyplz,con_keyfol,con_keydep,con_diapag,con_fecini,con_cosuni,con_numcap,con_keyemp,con_keypue,con_keytco,con_stspag,con_keytva ,con_fecoto,con_keyusg FROM holocont;
